j['slides']=[slide('Opening',2,'A precise checkpoint, then a useful next step',['Five questions, 20 core marks.','Short recap first; 18 minutes for independent work.'],'Explain that this is original selected-topic practice after a recap. Record the chosen route and support. No grade prediction or public score ranking.'),slide('Retrieval',2,'Retrieve a route and a process',['R1. What carries an endocrine hormone around the body?','R2. What is the difference between ventilation and diffusion?'],'R1 blood. R2 ventilation moves air through pressure changes; diffusion is net particle movement down a gradient. Accept spoken or pointed responses.'),slide('I do',3,'Trace the hormone message',['Gland releases a hormone into blood.','Responsive cells recognise the signal and change activity.'],'Think aloud through location → carrier → response. This general recap does not rehearse the checkpoint wording. Recognition explains why every cell does not respond identically.',visual=v1),slide('I do',2,'Read direction before oxygen content',['An artery takes blood away from the heart.','Follow the lung circuit to test the definition.'],'Trace right ventricle → pulmonary artery → lungs. It carries relatively oxygen-poor blood away from the heart. Let pupils see how the vessel definition differs from its oxygen content.',visual=v2),slide('I do',2,'Volume and pressure explain ventilation',['Inhalation increases volume and lowers pressure.','Quiet exhalation involves relaxation and recoil.'],'Trace one mechanical sequence. Distinguish the resulting airflow from diffusion across the alveolar barrier. This is a recap, not a breathing practical.',visual=v3),slide('We do',2,'Use an analogous calculation',['W1. Model M: 60 beats/min × 50 mL/beat.','Model N: 80 beats/min × 50 mL/beat.','Calculate N after the teacher models M.'],'Model M = 3,000 mL/min = 3 L/min. Joint N = 4,000 mL/min = 4 L/min. Cancel beat units, then divide by 1,000. These are warm-up records, not checkpoint A/B.',visual=v4),slide('We do',2,'Challenge a pair of claims',['W2. “All blood-carried hormones affect every cell equally.”','W3. “The pulmonary artery is a vein because its blood is oxygen-poor.”'],'W2 false: responsiveness/recognition matters. W3 false: it leaves the heart, so it is an artery. Pupils justify with a route rather than merely voting.'),slide('We do',1,'State what the calculation cannot show',['Warm-up N has greater volume output than M.','Does that alone prove a person is healthier?'],'No. These are constructed records; health, demand and oxygen content are not measured. Keep the conclusion to the supplied output comparison.'),slide('Hinge',1,'Before you begin',['Which practice will give a useful record of learning?'],'Correct: answer independently with agreed support recorded; review afterwards. Read the support record aloud if needed.',options=[option('Record the route and support; answer first; use feedback afterwards.',True,'That makes the evidence interpretable and keeps feedback separate from the attempt.'),option('Convert the total directly into a predicted GCSE grade.',False,'Twenty marks of selected teacher-authored content cannot establish an official grade.'),option('Copy the worked answers while completing the checkpoint.',False,'That would hide which ideas the pupil can currently apply.')]),slide('You do',1,'Set up your selected checkpoint route',['Use the shared source page and Q1–Q5.','All routes have the same 20 core marks.'],'Explain calculator and read-aloud access. Write the route/support on the feedback page before timing begins. Do not impose a penalty for the route choice.'),slide('You do',18,'Independent checkpoint: 18 minutes',['Answer Q1–Q5. Show units and causal links.','If stuck, move on and return.'],'Keep answer reveals closed. Offer agreed access support without supplying scientific content; record any additional content prompts. Optional challenge audit is unscored and only after the core.'),slide('Review',2,'Feedback starts now',['Pause or collect the first attempt.','Use item evidence to choose one correction.'],'Use the five four-mark item guides. A pupil can mark one selected item while teacher completes the rest after class; do not try to read every model answer aloud in two minutes. Preserve the original response before correction.'),slide('Review',1,'Audience: identify the next move',['L1. Share one correction with an adult or partner.','Say which mechanism or calculation it improves.'],'Accept a quiet conference. Convert “revise everything” into a specific action, such as pressure direction, mL-to-L conversion or hormone versus storage.'),slide('Exit',1,'Finish with a targeted action',['E1. Name one idea you can now explain.','E2. State one practice that would improve your next attempt.'],'No new scored science items. Use Q1–Q5 evidence to justify the chosen practice; avoid labelling a pupil by the score.'),slide('Exit',0,'Store the evidence, not a label',['Keep the attempt, route, support and correction together.'],'Shared exit minute. Retest with a fresh equivalent item later if useful; do not reuse the same answer as independent evidence.')]
